#include <random>
#include <iostream>

class MyEngine {
public:
    using result_type = unsigned int;
    MyEngine() { seed(); }
    explicit MyEngine(result_type s) { seed(s); }
    void seed() { state = 0; }
    void seed(result_type s) { state = s; }
    result_type operator()() {
        state = (state * 1664525 + 1013904223);
        return state;
    }
    void discard(unsigned long z) {
        for (unsigned long i = 0; i < z; ++i) {
            operator()();
        }
    }
    bool operator==(const MyEngine& other) const { return state == other.state; }
    bool operator!=(const MyEngine& other) const { return !(*this == other); }
    friend std::ostream& operator<<(std::ostream& os, const MyEngine& e) {
        os << e.state;
        return os;
    }
    friend std::istream& operator>>(std::istream& is, MyEngine& e) {
        is >> e.state;
        return is;
    }
private:
    result_type state;
};

class MyAdaptor {
public:
    explicit MyAdaptor(const MyEngine& base) : base_engine(base) {}
    const MyEngine& base() const { return base_engine; }
private:
    MyEngine base_engine;
};

int main() {
    MyEngine engine1;
    engine1.seed(42);
    std::cout << "Engine state: " << engine1 << std::endl;
    engine1.discard(10);
    std::cout << "After discard: " << engine1 << std::endl;
    MyEngine engine2 = engine1;
    std::cout << "Engines equal? " << (engine1 == engine2) << std::endl;
    std::stringstream ss;
    ss << engine1;
    MyEngine engine3;
    ss >> engine3;
    std::cout << "Engine3 state: " << engine3 << std::endl;
    MyAdaptor adaptor(engine1);
    std::cout << "Adaptor's base engine state: " << adaptor.base() << std::endl;
    return 0;
}
